1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ec; font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; flex-wrap: wrap; justify-content: center; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; padding: 1px; background: #262a33; border: 2px solid #3a3f4b; border-radius: 4px;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #0d0f14; }
20	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18), inset 0 -3px 0 rgba(0,0,0,0.25); }
21	  .panel { display: flex; flex-direction: column; gap: 14px; min-width: 150px; }
22	  .stat { background: #1c1f27; border: 1px solid #2c313c; border-radius: 6px; padding: 8px 12px; }
23	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9097a6; }
24	  .stat .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
25	  .next-list { display: flex; flex-direction: column; gap: 8px; margin-top: 6px; }
26	  .preview { display: grid; grid-template-columns: repeat(4, 20px); grid-template-rows: repeat(2, 20px); gap: 1px; }
27	  .preview .mini { width: 20px; height: 20px; background: transparent; }
28	  .preview .mini[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
29	  .status { min-height: 1.4em; color: #ff8a80; font-weight: 600; }
30	  .help { font-size: 13px; color: #9097a6; }
31	  .help kbd { background: #2c313c; border-radius: 3px; padding: 0 5px; color: #e8e8ec; font: inherit; }
32	  button {
33	    background: #3a6ff7; color: #fff; border: 0; border-radius: 6px; padding: 8px 12px;
34	    font: inherit; font-weight: 600; cursor: pointer;
35	  }
36	</style>
37	</head>
38	<body>
39	<div class="game">
40	  <div class="board" data-testid="board"></div>
41	  <div class="panel">
42	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score">0</div></div>
43	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level">1</div></div>
44	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines">0</div></div>
45	    <div class="stat"><div class="label">Next</div><div class="next-list" data-testid="next-piece"></div></div>
46	    <div class="status" data-testid="status"><span data-testid="game-over" hidden></span></div>
47	    <button type="button" id="new-game">New game</button>
48	    <div class="help">
49	      <kbd>←</kbd> <kbd>→</kbd> move<br>
50	      <kbd>↑</kbd> rotate<br>
51	      <kbd>↓</kbd> soft drop<br>
52	      <kbd>Space</kbd> hard drop
53	    </div>
54	  </div>
55	</div>
56	<script>
57	(function () {
58	  'use strict';
59	
60	  var ROWS = 20, COLS = 10;
61	  var TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
62	  var COLORS = {
63	    I: '#00bcd4', O: '#f5c400', T: '#9c27b0', S: '#43a047',
64	    Z: '#e53935', J: '#1e63d6', L: '#fb8c00'
65	  };
66	  // Spawn orientation, as [row, col] offsets from the piece origin.
67	  var SHAPES = {
68	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
69	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
70	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
71	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
72	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
73	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
74	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
75	  };
76	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
77	  var GRAVITY_MS = 1000;
78	  var PREVIEW_COUNT = 3;
79	
80	  // Clockwise rotation states. Each is a quarter turn of the one before, inside the
81	  // piece's box (2x2 for O, 3x3 for the rest). I is listed by hand so it turns about its middle.
82	  var ROTATIONS = {};
83	  TYPES.forEach(function (t) {
84	    var n = t === 'O' ? 2 : 3;
85	    var states = [SHAPES[t]];
86	    for (var k = 1; k < 4; k++) {
87	      states.push(states[k - 1].map(function (p) { return [p[1], n - 1 - p[0]]; }));
88	    }
89	    ROTATIONS[t] = states;
90	  });
91	  ROTATIONS.I = [
92	    SHAPES.I,
93	    [[0, 2], [1, 2], [2, 2], [3, 2]],
94	    [[1, 0], [1, 1], [1, 2], [1, 3]],
95	    [[0, 1], [1, 1], [2, 1], [3, 1]]
96	  ];
97	  // Sideways shifts tried, in order, when a rotated piece does not fit where it is.
98	  var KICKS = [0, -1, 1, -2, 2];
99	
100	  // Locking rule (a project decision): a gravity step that cannot move the piece down counts
101	  // one tick of lock delay; the piece locks on the LOCK_TICKS-th such tick. A successful left or
102	  // right move during the delay restarts it, at most MAX_RESTARTS times per piece. Hard drop
103	  // locks at once.
104	  var LOCK_TICKS = 2;
105	  var MAX_RESTARTS = 3;
106	
107	  // Scoring rule (a project decision): a clear scores LINE_POINTS[rows cleared at once] times the
108	  // current level. Clearing rows together must always beat clearing the same rows in smaller
109	  // groups, so every entry must exceed any sum of smaller entries that adds up to the same rows.
110	  // Soft drop scores 1 per cell moved down by the player; hard drop scores 2 per cell dropped.
111	  var LINE_POINTS = [0, 100, 300, 500, 800];
112	  var SOFT_DROP_POINTS = 1;
113	  var HARD_DROP_POINTS = 2;
114	
115	  // Game state. `board` holds the locked cells: a piece letter, or '' when empty.
116	  var board, current, queue, bag, score, level, lines, status, timer = null;
117	
118	  // ---- DOM ----
119	  var boardEl = document.querySelector('[data-testid="board"]');
120	  var scoreEl = document.querySelector('[data-testid="score"]');
121	  var levelEl = document.querySelector('[data-testid="level"]');
122	  var linesEl = document.querySelector('[data-testid="lines"]');
123	  var nextEl = document.querySelector('[data-testid="next-piece"]');
124	  var gameOverEl = document.querySelector('[data-testid="game-over"]');
125	  var cellEls = [];
126	  var itemEls = [];
127	  var miniEls = [];
128	
129	  for (var r = 0; r < ROWS; r++) {
130	    cellEls.push([]);
131	    for (var c = 0; c < COLS; c++) {
132	      var el = document.createElement('div');
133	      el.className = 'cell';
134	      el.setAttribute('data-testid', 'cell');
135	      el.setAttribute('data-row', String(r));
136	      el.setAttribute('data-col', String(c));
137	      boardEl.appendChild(el);
138	      cellEls[r].push(el);
139	    }
140	  }
141	  // One 4x2 mini grid per upcoming piece. The first grid keeps the older data-testid="next".
142	  for (var i = 0; i < PREVIEW_COUNT; i++) {
143	    var item = document.createElement('div');
144	    item.className = 'preview';
145	    item.setAttribute('data-testid', 'next-piece-item');
146	    nextEl.appendChild(item);
147	    itemEls.push(item);
148	    var grid = item;
149	    if (i === 0) {
150	      grid = document.createElement('div');
151	      grid.className = 'preview';
152	      grid.setAttribute('data-testid', 'next');
153	      item.className = '';
154	      item.appendChild(grid);
155	    }
156	    miniEls.push([]);
157	    for (var mr = 0; mr < 2; mr++) {
158	      miniEls[i].push([]);
159	      for (var mc = 0; mc < 4; mc++) {
160	        var m = document.createElement('div');
161	        m.className = 'mini';
162	        grid.appendChild(m);
163	        miniEls[i][mr].push(m);
164	      }
165	    }
166	  }
167	
168	  function paint(el, type) {
169	    el.setAttribute('data-filled', type ? 'true' : 'false');
170	    el.setAttribute('data-piece', type || '');
171	    el.style.backgroundColor = type ? COLORS[type] : '';
172	  }
173	
174	  function render() {
175	    var view = board.map(function (row) { return row.slice(); });
176	    if (current) {
177	      pieceCells(current).forEach(function (p) { view[p[0]][p[1]] = current.type; });
178	    }
179	    for (var r = 0; r < ROWS; r++) {
180	      for (var c = 0; c < COLS; c++) paint(cellEls[r][c], view[r][c]);
181	    }
182	
183	    for (var i = 0; i < PREVIEW_COUNT; i++) {
184	      var upcoming = queue[i] || '';
185	      itemEls[i].setAttribute('data-piece', upcoming);
186	      for (var mr = 0; mr < 2; mr++) {
187	        for (var mc = 0; mc < 4; mc++) paint(miniEls[i][mr][mc], '');
188	      }
189	      if (upcoming) {
190	        SHAPES[upcoming].forEach(function (p) { paint(miniEls[i][p[0]][p[1]], upcoming); });
191	      }
192	    }
193	
194	    scoreEl.textContent = String(score);
195	    levelEl.textContent = String(level);
196	    linesEl.textContent = String(lines);
197	    var over = status === 'gameover';
198	    gameOverEl.hidden = !over;
199	    gameOverEl.textContent = over ? 'Game over' : '';
200	  }
201	
202	  // ---- Pieces ----
203	  function randomPiece() {
204	    if (!bag.length) {
205	      bag = TYPES.slice();
206	      for (var i = bag.length - 1; i > 0; i--) {
207	        var j = Math.floor(Math.random() * (i + 1));
208	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
209	      }
210	    }
211	    return bag.pop();
212	  }
213	
214	  // Keep at least PREVIEW_COUNT pieces waiting, so the preview is always full.
215	  function fillQueue() {
216	    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
217	  }
218	
219	  function takeNext() {
220	    fillQueue();
221	    var type = queue.shift();
222	    fillQueue();
223	    return type;
224	  }
225	
226	  function pieceCells(piece) {
227	    return ROTATIONS[piece.type][piece.rot].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });
228	  }
229	
230	  function fits(cells) {
231	    return cells.every(function (p) {
232	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !board[p[0]][p[1]];
233	    });
234	  }
235	
236	  function spawn() {
237	    var type = takeNext();
238	    var piece = { type: type, row: 0, col: SPAWN_COL[type], rot: 0, lockTicks: 0, restarts: 0 };
239	    if (!fits(pieceCells(piece))) {
240	      current = null;
241	      status = 'gameover';
242	      stopTimer();
243	      return;
244	    }
245	    current = piece;
246	  }
247	
248	  function move(dr, dc) {
249	    if (!current) return false;
250	    var moved = { type: current.type, row: current.row + dr, col: current.col + dc, rot: current.rot };
251	    if (!fits(pieceCells(moved))) return false;
252	    current.row = moved.row;
253	    current.col = moved.col;
254	    return true;
255	  }
256	
257	  // Left or right. During the lock delay, a successful move restarts it, up to the cap.
258	  function shift(dc) {
259	    if (!move(0, dc)) return;
260	    if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
261	      current.lockTicks = 0;
262	      current.restarts++;
263	    }
264	  }
265	
266	  // Try the next clockwise state in place, then shifted sideways. If nothing fits, change nothing.
267	  function rotateCW() {
268	    if (!current) return false;
269	    var rot = (current.rot + 1) % 4;
270	    for (var i = 0; i < KICKS.length; i++) {
271	      var turned = { type: current.type, row: current.row, col: current.col + KICKS[i], rot: rot };
272	      if (fits(pieceCells(turned))) {
273	        current.col = turned.col;
274	        current.rot = rot;
275	        return true;
276	      }
277	    }
278	    return false;
279	  }
280	
281	  // Remove every full row; the rows above drop down. Returns how many rows went.
282	  function clearLines() {
283	    var kept = board.filter(function (row) { return !row.every(Boolean); });
284	    var cleared = ROWS - kept.length;
285	    for (var i = 0; i < cleared; i++) kept.unshift(new Array(COLS).fill(''));
286	    board = kept;
287	    return cleared;
288	  }
289	
290	  function lock() {
291	    pieceCells(current).forEach(function (p) { board[p[0]][p[1]] = current.type; });
292	    current = null;
293	    var cleared = clearLines();
294	    lines += cleared;
295	    score += LINE_POINTS[cleared] * level;
296	    spawn();
297	  }
298	
299	  // One gravity step. The real timer and tick() both run exactly this. Returns true if the piece moved down.
300	  function gravityStep() {
301	    if (status !== 'running' || !current) return false;
302	    if (move(1, 0)) {
303	      current.lockTicks = 0;
304	      return true;
305	    }
306	    current.lockTicks++;
307	    if (current.lockTicks >= LOCK_TICKS) lock();
308	    return false;
309	  }
310	
311	  function gravity() {
312	    gravityStep();
313	    render();
314	  }
315	
316	  function stopTimer() {
317	    if (timer !== null) { clearInterval(timer); timer = null; }
318	  }
319	
320	  function startTimer() {
321	    stopTimer();
322	    timer = setInterval(gravity, GRAVITY_MS);
323	  }
324	
325	  // ---- Actions ----
326	  function input(action) {
327	    if (status !== 'running' || !current) return;
328	    if (action === 'left') shift(-1);
329	    else if (action === 'right') shift(1);
330	    else if (action === 'rotateCW') rotateCW();
331	    else if (action === 'softDrop') {
332	      if (gravityStep()) score += SOFT_DROP_POINTS;
333	    }
334	    else if (action === 'hardDrop') {
335	      while (move(1, 0)) score += HARD_DROP_POINTS;
336	      lock();
337	    }
338	    render();
339	  }
340	
341	  function toQueue(list) {
342	    return (Array.isArray(list) ? list : [])
343	      .map(function (t) { return String(t).toUpperCase(); })
344	      .filter(function (t) { return SHAPES.hasOwnProperty(t); });
345	  }
346	
347	  function newGame(list) {
348	    board = [];
349	    for (var r = 0; r < ROWS; r++) board.push(new Array(COLS).fill(''));
350	    bag = [];
351	    queue = toQueue(list);
352	    score = 0;
353	    level = 1;
354	    lines = 0;
355	    status = 'running';
356	    current = null;
357	    spawn();
358	    if (status === 'running') startTimer();
359	    render();
360	  }
361	
362	  function setQueue(list) {
363	    queue = toQueue(list);
364	    fillQueue();
365	    render();
366	  }
367	
368	  function setBoard(rows) {
369	    for (var r = 0; r < ROWS; r++) {
370	      var line = rows && typeof rows[r] === 'string' ? rows[r] : '';
371	      for (var c = 0; c < COLS; c++) {
372	        var ch = line.charAt(c).toUpperCase();
373	        board[r][c] = SHAPES.hasOwnProperty(ch) ? ch : '';
374	      }
375	    }
376	    render();
377	  }
378	
379	  function getBoard() {
380	    return board.map(function (row) {
381	      return row.map(function (t) { return t || '.'; }).join('');
382	    });
383	  }
384	
385	  function getState() {
386	    return {
387	      current: current ? { type: current.type, cells: pieceCells(current) } : null,
388	      next: queue.slice(),
389	      score: score,
390	      level: level,
391	      lines: lines,
392	      status: status
393	    };
394	  }
395	
396	  function tick(n) {
397	    var steps = n === undefined ? 1 : n;
398	    for (var i = 0; i < steps; i++) gravity();
399	  }
400	
401	  window.__tetris = {
402	    newGame: newGame,
403	    setQueue: setQueue,
404	    setBoard: setBoard,
405	    tick: tick,
406	    input: input,
407	    getBoard: getBoard,
408	    getState: getState
409	  };
410	
411	  var KEYS = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'rotateCW', ArrowDown: 'softDrop', ' ': 'hardDrop', Spacebar: 'hardDrop' };
412	  document.addEventListener('keydown', function (e) {
413	    var action = KEYS[e.key];
414	    if (!action) return;
415	    e.preventDefault();
416	    input(action);
417	  });
418	  document.getElementById('new-game').addEventListener('click', function (e) {
419	    e.currentTarget.blur();
420	    newGame();
421	  });
422	
423	  newGame();
424	})();
425	</script>
426	</body>
427	</html>
