input.new_string:
function shift(dc) {
  if (move(0, dc)) restartLock();
}

// Down, one row. On a piece already resting it counts no lock tick and restarts the delay like a
// sideways move, sharing the same cap.
function softDrop() {
  if (move(1, 0)) {
    current.lockTicks = 0;
    score += SOFT_DROP_POINTS;
  } else {
    restartLock();
  }
}

function restartLock() {
  if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
    current.lockTicks = 0;
    current.restarts++;
  }
}

